using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

var services = new ServiceCollection();

services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Information));

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

services.AddChatClient(builder => builder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var logger = sp.GetRequiredService<ILogger<Program>>();

// Create the research agent with tools
var notepad = new NotepadTool();
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Given a topic, you:
        1. Search the web for relevant information using the search tool.
        2. Take notes on key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a concise summary.
        Always search at least 2-3 different queries to get comprehensive coverage.
        """,
    Tools = tools,
};

// Get topic from args or prompt the user
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Notes collected during research:");
foreach (var note in notepad.Notes)
{
    Console.WriteLine($"  • {note}");
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine();
    return string.IsNullOrWhiteSpace(topic)
        ? throw new InvalidOperationException("A topic is required.")
        : topic;
}

/// <summary>
/// Simulated web search tool. Replace with a real search API (e.g., Bing Search) for production use.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        // In production, replace with Bing Search API, Google Custom Search, etc.
        // This uses a free DuckDuckGo instant answer API as a demonstration.
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await Http.GetFromJsonAsync<JsonElement>(url, cancellationToken);
            var abstract_ = response.GetProperty("Abstract").GetString();
            var relatedTopics = response.GetProperty("RelatedTopics");

            var results = new List<string>();
            if (!string.IsNullOrEmpty(abstract_))
            {
                results.Add($"Summary: {abstract_}");
            }

            foreach (var topic in relatedTopics.EnumerateArray().Take(5))
            {
                if (topic.TryGetProperty("Text", out var text))
                {
                    results.Add(text.GetString() ?? "");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }
}

/// <summary>
/// A simple note-taking tool that allows the agent to record and retrieve findings.
/// </summary>
class NotepadTool
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Adds a note to the research notepad for later reference.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public string GetNotes()
    {
        return _notes.Count == 0
            ? "No notes taken yet."
            : string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

