 /// </summary>
 static class WebSearchTool
 {
     private static readonly HttpClient Http = new();

     [Description("Searches the web for information on a given query and returns relevant results.")]
     public static async Task<string> SearchWebAsync(
         [Description("The search query to look up")] string query,
         CancellationToken cancellationToken = default)
     {
         var encoded = Uri.EscapeDataString(query);
         var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

         try
         {
             var response = await Http.GetFromJsonAsync<JsonElement>(url, cancellationToken);
             var abstract_ = response.GetProperty("Abstract").GetString();
             var relatedTopics = response.GetProperty("RelatedTopics");

             var results = new List<string>();
             if (!string.IsNullOrEmpty(abstract_))
             {
                 results.Add($"Summary: {abstract_}");
             }

             foreach (var item in relatedTopics.EnumerateArray().Take(5))
             {
                 if (item.TryGetProperty("Text", out var text))
                 {
                     results.Add(text.GetString() ?? "");
                 }
             }

             return results.Count > 0
                 ? string.Join("\n", results)
                 : $"No detailed results found for '{query}'. Try rephrasing.";
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}";
         }
     }
 }

 /// <summary>
 /// A note-taking tool that allows the agent to record and retrieve findings.
