         return $"Note saved ({_notes.Count} total).";
     }

     [Description("Retrieves all notes taken so far during the research session.")]
     public string GetNotes()
     {
         return _notes.Count == 0
             ? "No notes taken yet."
             : string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
     }
 }

